package ai.petologic.security

import kotlinx.serialization.json.Json
import java.io.File
import kotlin.test.*

/**
 * Validates the staged (unsigned) protection content committed under updates-endpoint/content/
 * against the exact verifiers the app runs at update time. Skips when the directory is absent
 * (the content is regenerated by scripts/build-staged-content.py from the pinned ESET snapshot).
 */
class StagedContentContractTest {
 private val contentDir=sequenceOf(File("."),File("..")).firstNotNullOfOrNull{base->
   generateSequence(base){it.parentFile}.map{File(it,"updates-endpoint/content")}.firstOrNull{it.isDirectory}}?.absoluteFile
   ?: File("updates-endpoint/content")

 @Test fun stagedHashPackMatchesThreatPackBounds(){
  if(!contentDir.resolve("hash-pack.json").exists())return
  val pack=Json.decodeFromString<ThreatPack>(contentDir.resolve("hash-pack.json").readText())
  assertTrue(pack.schema==1&&pack.minEngine==1)
  assertTrue(pack.indicators.size in 1..10_000)
  assertTrue(pack.indicators.map{it.sha256}.distinct().size==pack.indicators.size)
  assertTrue(pack.indicators.all{Regex("[0-9a-f]{64}").matches(it.sha256)})
  assertTrue(pack.indicators.all{it.id.length<=160&&it.source.length<=512&&it.license.length<=80})
 }
 @Test fun stagedKnowledgePackPassesSecurityKnowledgePackVerifier(){
  if(!contentDir.resolve("knowledge-pack.json").exists())return
  val bytes=contentDir.resolve("knowledge-pack.json").readBytes()
  val verified=SecurityKnowledgePackVerifier.verify(bytes,packVersion(),System.currentTimeMillis())
  assertTrue(verified.records.isNotEmpty())
  assertEquals(verified.records.size,verified.records.map{it.id}.distinct().size)
 }
 @Test fun stagedReputationInputsMatchPackIndicators(){
  val rep=contentDir.resolve("reputation-indicators.json");val pack=contentDir.resolve("hash-pack.json")
  if(!(rep.exists()&&pack.exists()))return
  val inputs=Json.decodeFromString<List<ReputationIndicatorInput>>(rep.readText())
  val hashes=Json.decodeFromString<ThreatPack>(pack.readText()).indicators.map{it.sha256}.toSet()
  assertTrue(inputs.isNotEmpty()&&inputs.all{it.sha256 in hashes})
 }
 @Test fun stagedVersionsMatchManifestVersion(){
  val files=contentDir.listFiles().orEmpty().filter{it.extension=="json"}
  if(files.isEmpty())return
  val versions=files.map{Json.decodeFromString<VersionedStaged>(it.readBytes().decodeToString()).version}.distinct()
  assertTrue(versions.size==1,"Staged content versions must move together: $versions")
 }
 private fun packVersion():Long{
  val pack=contentDir.resolve("hash-pack.json").readText()
  return Json.decodeFromString<ThreatPack>(pack).version
 }
}

@kotlinx.serialization.Serializable
private data class ReputationIndicatorInput(val sha256:String,val indicatorId:String,val sourceId:String)

@kotlinx.serialization.Serializable
private data class VersionedStaged(val version:Long)
